  "entity.recipe.cook_fish.description": "생선 요리 1인분. 전투 시작 시 사용해 본인의 일반 공격 +10%(전투 시간 90초). 전투 중에는 다시 먹지 않습니다.",
  "entity.recipe.tempo_ring.name": "질풍의 반지",
  "entity.recipe.tempo_ring.description": "공격 속도 +20%, 방어 −3. 공격 횟수와 내구력 중 선택. 한 번 제작하면 영구 보유.",
  "entity.recipe.steady_ring.name": "필중의 반지",
  "entity.recipe.steady_ring.description": "치명타 게이지 +25%. 4타마다 치명타, 치명타 위력 +25%. 한 번 제작하면 영구 보유.",
  "entity.recipe.guard_bracelet.name": "반격의 팔찌",
  "entity.recipe.guard_bracelet.description": "방어 +4. 적의 공격을 견디면 방어력의 20%로 1회 반격. 한 번 제작하면 영구 보유.",
  "entity.recipe.artisan_bracelet.name": "장인의 팔찌",
  "entity.recipe.artisan_bracelet.description": "준비 중 채집·제작 속도 +15%. 훈련은 제외. 한 번 제작하면 영구 보유.",
  "entity.recipe.river_pendant.name": "계류의 목걸이",
  "entity.recipe.river_pendant.description": "MP 재생 +0.75/초, 마법 피해 −5%. 장기전의 MP 유지와 한 방의 화력 중 선택. 한 번 제작하면 영구 보유.",
  "entity.recipe.forge_ring.name": "잿더미의 반지",
  "entity.recipe.forge_ring.description": "치명타 배율 +50%, 방어 −3. 치명타 게이지는 계승·무기로 구성. 한 번 제작하면 영구 보유.",
  "entity.recipe.star_bracelet.name": "별관측 팔찌",
  "entity.recipe.star_bracelet.description": "마법 피해 +15%, 방어 −3. 반격·방어 팔찌와의 선택. 한 번 제작하면 영구 보유.",
  "entity.recipe.ice_boots.name": "빙관의 신발",
  "entity.recipe.ice_boots.description": "방어 +8, 공격 속도 −10%. 속공과 내구력 중 선택. 한 번 제작하면 영구 보유.",
  "entity.recipe.angler_pendant.name": "낚시꾼의 목걸이",
  "entity.recipe.angler_pendant.description": "본인 낚시 속도 +15%. 채집 장인·요리·전투에는 효과 없음. 한 번 제작하면 영구 보유.",
  "entity.recipe.runner_boots.name": "질주의 신발",
  "entity.recipe.runner_boots.description": "전투 공격 속도 +10%, 방어 −2. 무기 속도는 최대 1.6배. 한 번 제작하면 영구 보유.",
  "entity.recipe.work_boots.name": "작업 신발",
  "entity.recipe.work_boots.description": "준비 중 채집·제작 속도 +10%. 훈련/채집 장인/산란 주기는 바뀌지 않습니다. 한 번 제작하면 영구 보유.",
  "entity.recipe.sage_boots.name": "현자의 신발",
  "entity.recipe.sage_boots.description": "전투 마법 피해 +10%, MP 재생 +0.25/초. 최대 MP 30. 한 번 제작하면 영구 보유.",
  "entity.recipe.battle_pendant.name": "전사의 목걸이",
  "entity.recipe.battle_pendant.description": "치명타 배율 +15%, 방어 −1. 치명타 게이지는 반지와 계승으로 선택. 한 번 제작하면 영구 보유.",
  "entity.recipe.guild_pendant.name": "공예가의 목걸이",
  "entity.recipe.guild_pendant.description": "준비 중 채집·제작 속도 +10%. 채집 장인/산란/훈련은 별도. 한 번 제작하면 영구 보유.",
  "entity.recipe.ember_pendant.name": "불씨 목걸이",
  "entity.recipe.ember_pendant.description": "전투 마법 피해 +15%. 물리 치명타·MP 소모·주문 간격은 바뀌지 않습니다. 한 번 제작하면 영구 보유.",
  "entity.recipe.mix_spark.name": "불꽃 촉매 조제",
  "entity.recipe.mix_spark.description": "약초 4와 목재 1로 촉매 3. 최대 12. 해당 증강 발동 시 1 소모.",
  "entity.recipe.mix_ward.name": "부적액 조제",
  "entity.recipe.mix_ward.description": "약초 3과 돌 2로 부적액 2. 최대 12. 큰 적 공격을 18 경감하고 1 소모(6초 간격). 물리·마법 모두 유효.",
  "entity.recipe.egg_stew.name": "달걀 스튜",
  "entity.recipe.egg_stew.description": "달걀 요리 1인분. 전투 시작 시 사용해 일반 공격 속도 +15%(전투 시간 90초). 전투 중에는 다시 먹지 않습니다.",
