  "route.guide": "공통 규칙·획득 중인 효과",
  "route.guideText": "개척 거점은 준비 중에만 생산합니다. 인구는 인력 화면에서 공유합니다. 최초 돌파 후 다음 생에서 재개척을 예약할 수 있습니다. 입구는 이번 생에서 WAVE3 돌파 후 열립니다. 출발하려면 다음 본선 습격까지 30초 이상 남아야 합니다. 습격 예정은 바뀌지 않습니다. 패배하면 HP 1로 귀환하며 사용한 식량·연금 재료는 돌아오지 않습니다. 지역마다 생애당 1회입니다.",
